{"task_id": "T36", "code": "def solve(tokens):
    """Evaluate Reverse Polish Notation robustly.
    Supports integers (including sign) and the operators +, -, *, /.
    Division truncates toward zero.
    Empty token strings or whitespace are ignored.
    Division by zero returns 0 (as a safe fallback).
    """
    stack = []
    for raw in tokens:
        t = str(raw).strip()
        if not t:
            continue
        if t in ('+', '-', '*', '/') and len(t) == 1:
            # operator
            if len(stack) < 2:
                # malformed expression, skip
                continue
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division
                if b == 0:
                    # avoid ZeroDivisionError, define result as 0
                    stack.append(0)
                else:
                    # truncate toward zero without using float
                    sign = -1 if (a < 0) ^ (b < 0) else 1
                    stack.append(sign * (abs(a) // abs(b)))
        else:
            # operand
            try:
                stack.append(int(t))
            except ValueError:
                # non-integer token, ignore
                continue
    return stack[-1] if stack else 0"}

